import itertools, sys

def all_clauses(vars):
    lits = []
    for combo in itertools.combinations(vars, 3):
        for signs in itertools.product([1,-1], repeat=3):
            clause = [s*v for s,v in zip(signs, combo)]
            # ensure no var repeated (already distinct) and not both polarities (impossible)
            lits.append(clause)
    return lits

def is_sat(clauses, num_vars):
    for assign in itertools.product([False, True], repeat=num_vars):
        ok=True
        for clause in clauses:
            satisfied=False
            for lit in clause:
                var=abs(lit)-1
                val=assign[var]
                if lit>0 and val:
                    satisfied=True
                if lit<0 and not val:
                    satisfied=True
                if satisfied:
                    break
            if not satisfied:
                ok=False
                break
        if ok:
            return True
    return False

vars=[1,2,3]
clauses=all_clauses(vars)
# try small sets
for r in range(1,6):
    for combo in itertools.combinations(clauses, r):
        if not is_sat(combo, 3):
            print('found unsat set size', r)
            for c in combo:
                print(c)
            sys.exit()
print('none found up to 5')
